// ============================================================
// DER VORLESER · nimmt die Stimme, die im Rechner steckt.
// Play und Pause — und zwar echtes Pausieren, nicht von vorn.
// Nur im Pult, sonst nirgends.
// ============================================================
function machVorleser() {
  let laeuft = null;
  return {
    da: typeof window !== "undefined" && "speechSynthesis" in window,
    lies(text, beiEnde) {
      const rede = window.speechSynthesis;
      rede.cancel();
      const t = (text || "").trim();
      if (!t) return false;
      const spruch = new SpeechSynthesisUtterance(t);
      spruch.lang = "de-DE";
      spruch.rate = 0.95;
      const stimmen = rede.getVoices().filter((v) => v.lang && v.lang.startsWith("de"));
      if (stimmen.length) spruch.voice = stimmen[0];
      spruch.onend = () => { laeuft = null; beiEnde && beiEnde(); };
      spruch.onerror = () => { laeuft = null; beiEnde && beiEnde(); };
      laeuft = spruch;
      rede.speak(spruch);
      return true;
    },
    anhalten() { window.speechSynthesis.pause(); },
    weiter() { window.speechSynthesis.resume(); },
    aus() { laeuft = null; window.speechSynthesis.cancel(); },
    redetGerade() { return !!laeuft; },
  };
}
const vorleser = typeof window !== "undefined" ? machVorleser() : { da: false };

// Der Glockenschlag. Eine glocke klingt nicht wie ein einzelner ton, sondern
// wie mehrere, die nicht ganz zueinander passen und verschieden schnell
// verklingen — genau das bauen wir hier zusammen.
function glockeSchlagen() {
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const k = new AC();
    const jetzt = k.currentTime;
    const grund = 466;                                  // etwa ein b
    const teiltoene = [
      { mal: 0.5,  laut: 0.30, dauer: 4.5 },            // der brummton darunter
      { mal: 1.0,  laut: 0.42, dauer: 3.6 },
      { mal: 1.19, laut: 0.22, dauer: 2.4 },            // die kleine terz macht den glockenklang
      { mal: 1.5,  laut: 0.16, dauer: 1.8 },
      { mal: 2.0,  laut: 0.13, dauer: 1.2 },
      { mal: 2.66, laut: 0.09, dauer: 0.7 },
      { mal: 3.35, laut: 0.06, dauer: 0.45 },           // das anschlaggeräusch
    ];
    const summe = k.createGain();
    summe.gain.value = 0.5;
    summe.connect(k.destination);

    teiltoene.forEach((t) => {
      const o = k.createOscillator();
      const g = k.createGain();
      o.type = "sine";
      o.frequency.value = grund * t.mal;
      g.gain.setValueAtTime(0, jetzt);
      g.gain.linearRampToValueAtTime(t.laut, jetzt + 0.004);   // der schlag
      g.gain.exponentialRampToValueAtTime(0.0001, jetzt + t.dauer);
      o.connect(g); g.connect(summe);
      o.start(jetzt);
      o.stop(jetzt + t.dauer + 0.1);
    });
    setTimeout(() => k.close(), 5200);
  } catch {}
}

// ---- das Tagewerk ----
const heute = () => {
  const d = new Date();
  return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0")
    + "-" + String(d.getDate()).padStart(2, "0");
};

// Wie viele Tage hintereinander wurde das Ziel geschafft? Der heutige Tag
// zaehlt nur mit, wenn er schon geschafft ist — sonst haelt die kette
// bis mitternacht, statt gleich morgens zu reissen.
function ketteZaehlen(tage, ziel) {
  const geschafft = new Set(
    tage.filter((t) => (t.woerter - t.start) >= ziel).map((t) => t.tag));
  const d = new Date();
  if (!geschafft.has(heute())) d.setDate(d.getDate() - 1);   // heute noch offen: ab gestern
  let n = 0;
  for (;;) {
    const s = d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0")
      + "-" + String(d.getDate()).padStart(2, "0");
    if (!geschafft.has(s)) break;
    n++;
    d.setDate(d.getDate() - 1);
  }
  return n;
}

// Links aus einem Text fischen. In einem Schreibfeld kann nichts anklickbar
// sein — darum sammeln wir sie ein und legen sie unter den Bogen.
const LINK_MUSTER = /\b((?:https?:\/\/|www\.)[^\s<>"')\]]+)/gi;

function linkeFinden(text) {
  const roh = String(text || "").match(LINK_MUSTER) || [];
  const gesehen = new Set();
  const raus = [];
  for (let l of roh) {
    l = l.replace(/[.,;:!?»«"'\)\]]+$/, "");        // satzzeichen am ende gehoeren nicht dazu
    if (l.length < 8) continue;
    const voll = l.startsWith("www.") ? "https://" + l : l;
    if (gesehen.has(voll)) continue;
    gesehen.add(voll);
    let name = voll;
    try {
      const u = new URL(voll);
      name = u.hostname.replace(/^www\./, "") + (u.pathname !== "/" ? u.pathname : "");
    } catch {}
    raus.push({ voll, name: name.length > 44 ? name.slice(0, 42) + "…" : name });
  }
  return raus;
}

// Funken: kleine lichtpunkte, die auftauchen und wieder verloeschen.
// jeder bekommt seinen eigenen platz, seine eigene groesse und sein
// eigenes tempo, damit nichts im gleichschritt blinkt.
function machFunken(anzahl) {
  return Array.from({ length: anzahl }, (_, i) => {
    // jeder achte ist ein dicker — ein glutstueck statt eines fuenkchens
    const dick = i % 8 === 3;
    return {
      id: i,
      x: Math.random() * 100,
      y: Math.random() * 100,
      gross: dick ? 4 + Math.random() * 3.5 : 1.1 + Math.random() * 2.4,
      dauer: dick ? 5 + Math.random() * 5 : 3 + Math.random() * 5,
      warten: Math.random() * 7,
      weite: (dick ? 16 : 8) + Math.random() * 22,   // wie weit er dabei steigt
      dick,
    };
  });
}

function Funken() {
  const punkte = useRef(machFunken(58)).current;
  return (
    <div className="funkenfeld" aria-hidden="true">
      {punkte.map((f) => (
        <i key={f.id} className={"funke" + (f.dick ? " glut" : "")} style={{
          left: f.x + "%", top: f.y + "%",
          width: f.gross + "px", height: f.gross + "px",
          animationDuration: f.dauer + "s",
          animationDelay: f.warten + "s",
          "--weite": "-" + f.weite + "px",
        }} />
      ))}
    </div>
  );
}

// erst nach reihe, dann nach platz — wie man eine auslage liest
const sortiere = (a, b) => ((a.zeile || 0) - (b.zeile || 0)) || (a.pos - b.pos);

// Eine SPALTE ist alles, was auf demselben platz uebereinanderliegt:
// unten die szene, darueber ort, pov, gegenstand. Sie gehoert zusammen
// und wandert zusammen.
const spalteVon = (karten, pos) =>
  karten.filter((k) => k.pos === pos).sort((a, b) => (a.zeile || 0) - (b.zeile || 0));

// die UNTERSTE karte ist das fundament — sie traegt die spalte
const istFundament = (karten, k) => {
  const sp = spalteVon(karten, k.pos);
  return sp.length > 0 && sp[sp.length - 1].id === k.id;
};
const zaehle = (t) => (t && t.trim() ? t.trim().split(/\s+/).filter(Boolean).length : 0);

// Anmeldung merken, wo es geht. In der Vorschau gibt es keinen Speicher —
// dann lebt sie eben nur bis zum Neuladen.
let sitzungMerk = null;
const sitzungLesen = () => {
  if (sitzungMerk) return sitzungMerk;
  try { const r = localStorage.getItem("sk:sitzung"); return r ? JSON.parse(r) : null; } catch { return null; }
};
const sitzungSchreiben = (s) => {
  // wann laeuft der zugang ab? supabase gibt expires_in in sekunden.
  if (s && !s.expires_at && s.expires_in) s.expires_at = Math.floor(Date.now() / 1000) + s.expires_in;
  sitzungMerk = s;
  try { s ? localStorage.setItem("sk:sitzung", JSON.stringify(s)) : localStorage.removeItem("sk:sitzung"); } catch {}
};

// Den Zugang verlaengern, statt sich jede stunde neu anmelden zu muessen.
// Supabase gibt dafuer ein zweites papier mit: den refresh_token.
//
// WICHTIG: der schein gilt nur EINMAL. beim laden gehen aber drei anfragen
// gleichzeitig raus — wuerde jede fuer sich verlaengern, verbraucht die erste
// den schein und die anderen greifen ins leere. darum teilen sich alle
// dieselbe verlaengerung: laeuft schon eine, warten sie einfach mit.
let laufendeVerlaengerung = null;

function verlaengern(alt) {
  if (!alt || !alt.refresh_token) return Promise.resolve(null);
  if (laufendeVerlaengerung) return laufendeVerlaengerung;

  laufendeVerlaengerung = (async () => {
    try {
      const abbruch = new AbortController();
      const uhr = setTimeout(() => abbruch.abort(), 15000);
      const r = await fetch(URL_DB + "/auth/v1/token?grant_type=refresh_token", {
        method: "POST",
        headers: { apikey: KEY_DB, "Content-Type": "application/json" },
        body: JSON.stringify({ refresh_token: alt.refresh_token }),
        signal: abbruch.signal,
      });
      clearTimeout(uhr);
      if (!r.ok) return null;
      const neu = await r.json();
      if (!neu || !neu.access_token) return null;
      sitzungSchreiben(neu);
      return neu;
    } catch { return null; }
    finally { setTimeout(() => { laufendeVerlaengerung = null; }, 0); }
  })();

  return laufendeVerlaengerung;
}

// ============================================================
// DIE WARTESCHLANGE
// Ist das netz weg, geht nichts verloren: jede aenderung wird
// aufgeschrieben und nachgereicht, sobald es wieder da ist.
// Sie liegt im browser, ueberlebt also auch ein neuladen.
// ============================================================
const WARTE_SCHUB = "sk:warteschlange";

let warteMerk = null;
const warteLesen = () => {
  if (warteMerk) return warteMerk;
  try { warteMerk = JSON.parse(localStorage.getItem(WARTE_SCHUB) || "[]"); }
  catch { warteMerk = []; }
  return warteMerk;
};
const warteSchreiben = (l) => {
  warteMerk = l;
  try { localStorage.setItem(WARTE_SCHUB, JSON.stringify(l)); } catch {}
};
const warteAnhaengen = (auftrag) => {
  const l = [...warteLesen(), { ...auftrag, wann: Date.now() }];
  warteSchreiben(l);
  return l.length;
};

// war das ein netzproblem — oder hat die datenbank ordentlich nein gesagt?
const istNetzweg = (e) =>
  e && (e.name === "AbortError" || /netz|verbindung|antwortet nicht|failed|network|load/i.test(String(e.message)));

// ---------- Sprechen mit der Datenbank ----------
function machApi(holSitzung, setzeSitzung, abmelden) {
  const schicken = async (methode, pfad, koerper, extra, marke) => {
    const abbruch = new AbortController();
    const uhr = setTimeout(() => abbruch.abort(), 20000);
    try {
      return await fetch(URL_DB + pfad, {
        method: methode,
        headers: {
          apikey: KEY_DB,
          Authorization: "Bearer " + (marke || KEY_DB),
          "Content-Type": "application/json",
          ...extra,
        },
        body: koerper === undefined ? undefined : JSON.stringify(koerper),
        signal: abbruch.signal,
      });
    } catch (e) {
      throw new Error(e.name === "AbortError"
        ? "die datenbank antwortet nicht"
        : (e.message || "keine verbindung"));
    } finally { clearTimeout(uhr); }
  };

  return async function api(methode, pfad, koerper, extra) {
    let sitzung = holSitzung();
    // laeuft der zugang gleich ab? dann vorher still verlaengern.
    if (sitzung && sitzung.expires_at && sitzung.expires_at - 60 < Date.now() / 1000) {
      const neu = await verlaengern(sitzung);
      if (neu) { sitzung = neu; setzeSitzung(neu); }
    }
    let r = await schicken(methode, pfad, koerper, extra, sitzung && sitzung.access_token);

    // trotzdem abgelaufen? einmal verlaengern und noch einmal versuchen.
    if (r.status === 401 && sitzung) {
      const neu = await verlaengern(sitzung);
      if (neu) {
        setzeSitzung(neu);
        r = await schicken(methode, pfad, koerper, extra, neu.access_token);
      }
    }
    if (r.status === 401) { abmelden && abmelden(); throw new Error("abgemeldet"); }
    if (!r.ok) throw new Error((await r.text()).slice(0, 200) || ("status " + r.status));
    const t = await r.text();
    return t ? JSON.parse(t) : null;
  };
}

// dieselbe api, aber schreibende auftraege wandern bei netzproblemen
// in die warteschlange statt verloren zu gehen
function machApiMitNetz(api, melde) {
  return async function (methode, pfad, koerper, extra) {
    try {
      return await api(methode, pfad, koerper, extra);
    } catch (e) {
      const schreibt = methode !== "GET";
      const anmeldung = /abgemeldet/.test(String(e.message));
      if (schreibt && !anmeldung && istNetzweg(e)) {
        const n = warteAnhaengen({ methode, pfad, koerper, extra });
        melde && melde(n);
        return null;                 // die aenderung steht ja schon auf dem schirm
      }
      throw e;
    }
  };
}

// Kacheln liegen unregelmaessig — aber immer gleich unregelmaessig.
const streuung = (id) => {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) % 997;
  return { breit: [200, 250, 300, 230][h % 4], kipp: ((h % 5) - 2) * 0.35, hoch: (h % 3) * 4 };
};

